using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluations;

[TestClass]
public class ChatEvaluations
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        var chatConfig = new ChatConfiguration(GetChatClient);
        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"),
            chatConfiguration: chatConfig,
            evaluators: evaluators);
    }

    private static IChatClient GetChatClient(ChatConfiguration chatConfiguration)
    {
        // Uses the Azure OpenAI endpoint configured via environment variables:
        // AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_CHAT_MODEL (or defaults to gpt-4o-mini)
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the AZURE_OPENAI_ENDPOINT environment variable.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(
                Environment.GetEnvironmentVariable("AZURE_OPENAI_CHAT_MODEL") ?? "gpt-4o-mini")
            .AsIChatClient();
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            TestContext.CurrentContext!);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await scenario.ChatConfiguration!
            .ChatClientProvider(scenario.ChatConfiguration)
            .GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            TestContext.CurrentContext!);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "Explain what .NET Aspire is.")
        };

        var response = await scenario.ChatConfiguration!
            .ChatClientProvider(scenario.ChatConfiguration)
            .GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_HandlesMultiTurn()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            TestContext.CurrentContext!);

        var chatClient = scenario.ChatConfiguration!
            .ChatClientProvider(scenario.ChatConfiguration);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm building a web API with .NET. What framework should I use?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "How do I add authentication to it?"));
        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    public TestContext TestContext { get; set; } = null!;
}

